import {test} from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawn,spawnSync} from 'node:child_process';
import {EventEmitter} from 'node:events';
import * as m from '../scripts/mutagate.mjs';
import {inputFiles} from '../scripts/inputs.cjs';
import {tomlConfig,bridgeSource} from '../scripts/mutmut-bridge.cjs';
import {scrubEnv,recordedPayload} from './scratch.mjs';
function fixture(t, config={}) {const repo=fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'mutagate-')));t.after(()=>fs.rmSync(repo,{recursive:true,force:true}));const put=(f,s)=>{fs.mkdirSync(path.dirname(path.join(repo,f)),{recursive:true});fs.writeFileSync(path.join(repo,f),s);};put('src/main/java/acme/Foo.java','package acme; public class Foo { public int price(int n) { return n >= 5 ? 10 : 20; }}');put('src/test/java/acme/FooTest.java','package acme; public class FooTest {}');put('build.gradle',"plugins { id 'java' }");const root=path.join(repo,'.cache'),data=path.join(root,'repos',m.hash(repo));const c={repo,root,data,session:'test',sid:'test',harness:'claude',args:{},config:{...structuredClone(m.DEFAULTS),...config},errors:[],stateFile:path.join(data,'state/test.json')};return {c,put,test:'src/test/java/acme/FooTest.java',source:'src/main/java/acme/Foo.java'};}
const raw=(status='SURVIVED',line=1)=>[{file:'Foo.java',class:'acme.Foo',line,method:'price',mutator:'CONDITIONALS_BOUNDARY',description:'changed conditional boundary',status}];
test('clipped retry invalidates a prior error and stays pending',async t=>{const {c,test:file}=fixture(t,{gateBudgetSec:1});await m.register(c,file);const key=m.hash('acme.Foo');await m.runTarget(c,key,async()=>{throw Error('runner failed (1): missing JDK');});const before=m.state(c).targets[key].lastRunMs;let calls=0;const g=await m.gate(c,{hook:true,runner:async()=>{calls++;throw Error('runner failed (SIGKILL)');}});assert.equal(g.code,1);assert.equal(g.block,true);assert.match(g.reason,/results pending/);assert.equal(calls,1);assert.equal(m.loadResult(c,key,m.state(c).targets[key]),null);assert.ok(m.state(c).targets[key].lastRunMs>=before);});
async function scored(t,status='SURVIVED',config={}) {const f=fixture(t,config);await m.register(f.c,f.test);f.key=m.hash('acme.Foo');await m.runTarget(f.c,f.key,async()=>({raw:raw(status)}));return f;}
test('default globs and custom test matching',()=>{for(const f of ['src/test/java/A.java','FooTests.kt','x/test_foo.py','x/foo_test.py','src/foo.spec.ts','__tests__/foo.js'])assert.equal(m.isTest(f),true,f);for(const f of ['tests/conftest.py','tests/__init__.py','tests/test_x.py'])assert.equal(m.isTest(f),true,f);assert.equal(m.isTest('src/main/java/Foo.java'),false);assert.equal(m.isTest('foo.spec.ts',{...m.DEFAULTS,testGlobs:['checks/**']}),false);});
test('patch extracts adds, edits, removals and moves without executing text',()=>assert.deepEqual(m.extractPaths({tool_name:'apply_patch',tool_input:{command:'*** Begin Patch\n*** Add File: a.test.ts\n*** Update File: a.ts\n*** Move to: b.ts\n*** Delete File: c.ts\n*** End Patch'}}),['a.test.ts','a.ts','b.ts','c.ts']));
test('path confinement rejects traversal and symlink escape',t=>{const {c}=fixture(t);assert.equal(m.safePath(c.repo,'../outside'),null);fs.symlinkSync(os.tmpdir(),path.join(c.repo,'escape'),'dir');assert.equal(m.safePath(c.repo,'escape/file'),null);assert.equal(m.safePath(c.repo,'new/file'),path.join(c.repo,'new/file'));});
test('path confinement resolves a symlinked alias of the repo before the containment check',t=>{const {c}=fixture(t),dir=fs.mkdtempSync(path.join(os.tmpdir(),'alias-')),alias=path.join(dir,'repo');t.after(()=>fs.rmSync(dir,{recursive:true,force:true}));fs.symlinkSync(c.repo,alias,'dir');assert.equal(m.safePath(c.repo,path.join(alias,'src/test/java/acme/FooTest.java')),path.join(c.repo,'src/test/java/acme/FooTest.java'));assert.equal(m.safePath(c.repo,path.join(alias,'new/file')),path.join(c.repo,'new/file'));assert.equal(m.safePath(c.repo,path.join(dir,'other')),null);});
test('configuration precedence, type checks and safe defaults',t=>{const {c,put}=fixture(t);put('.mutagate/config.json','{"threshold":0.6}');assert.equal(m.configFor(c.repo,c.root,{threshold:'0.9'},{MUTAGATE_THRESHOLD:'0.7'}).config.threshold,.9);assert.equal(m.configFor(c.repo,c.root,{},{}).config.threshold,.6);assert.equal(m.configFor(c.repo,c.root,{threshold:'2'},{}).config.threshold,.8);});
test('target selection resolves package and ambiguous explicit selection',async t=>{const f=fixture(t);assert.equal(m.resolveTargets(f.c,f.test).targets[0].target,'acme.Foo');f.put('src/main/kotlin/acme/Foo.kt','package acme\nclass Foo');assert.equal(m.resolveTargets(f.c,f.test).ambiguous,true);const r=await m.register(f.c,f.test,'src/main/java/acme/Foo.java');assert.equal(r.targets.length,1);assert.equal(m.resolveTargets(f.c,f.test).targets.length,1);});
test('Kotlin PIT targets include the file facade, honoring JvmName, and its continuations are filtered',t=>{const {c,put}=fixture(t);const kt=src=>{put('src/main/kotlin/acme/Foo.kt',src);return m.runners().pitTargets(c,{target:'acme.Foo',language:'kotlin',file:'src/main/kotlin/acme/Foo.kt'});};assert.equal(m.runners().pitTargets(c,{target:'acme.Foo',language:'java',file:'src/main/java/acme/Foo.java'}),'acme.Foo,acme.Foo$*');assert.equal(kt('package acme\nclass Foo\nprivate fun x() = 1'),'acme.Foo,acme.Foo$*,acme.FooKt,acme.FooKt$*');assert.equal(kt('@file:JvmName("Tools")\npackage acme\nclass Foo'),'acme.Foo,acme.Foo$*,acme.Tools,acme.Tools$*');assert.equal(m.junkRule({file:'src/main/kotlin/acme/Foo.kt',class:'acme.FooKt$load$1',method:'invokeSuspend',line:0},[],'package acme\nsuspend fun load() = 1')?.id,'source-continuation');});
test('PIT parser preserves escaped descriptions and CSV handles quoting',()=>{assert.equal(m.parsePitXML('<mutations><mutation status="SURVIVED"><sourceFile>Foo.kt</sourceFile><mutatedClass>a.Foo</mutatedClass><mutatedMethod>x</mutatedMethod><lineNumber>42</lineNumber><mutator>MATH</mutator><description>a &gt; b &amp; c</description></mutation></mutations>')[0].description,'a > b & c');assert.deepEqual(m.parseCSV('a,"b,c","a""b"\r\n'),[['a','b,c','a"b']]);});
test('PIT EQUIVALENT mutants parse as ignored NON_VIABLE and count neither in the score nor as errored',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],xml=s=>`<mutation detected='false' status='${s}' numberOfTestsRun='0'><sourceFile>Foo.java</sourceFile><mutatedClass>acme.Foo</mutatedClass><mutatedMethod>price</mutatedMethod><lineNumber>1</lineNumber><mutator>MATH</mutator><description>${s}</description></mutation>`,r=m.parsePitXML(`<mutations partial='false'>${xml('KILLED')}${xml('EQUIVALENT')}</mutations>`);assert.deepEqual(r.map(x=>[x.status,x.ignored]),[['KILLED',undefined],['NON_VIABLE',true]]);const n=m.normalize(r,f.c,target);assert.deepEqual([n.score,n.killed,n.error_mutants,n.status],[1,1,0,'pass']);assert.match(m.normalize(r.slice(1),f.c,target).error,/^no mutants to test/);});
test('score counts timeouts, coverage, errors and zero eligible mutants',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],rr=m.normalize([...raw('KILLED'),...raw('TIMED_OUT',2),...raw('NO_COVERAGE',3),...raw('RUN_ERROR',4)],f.c,target);assert.equal(rr.score,2/3);assert.equal(rr.timed_out,1);assert.equal(rr.no_coverage,1);assert.equal(rr.error_mutants,1);assert.equal(m.normalize([],f.c,target).status,'unscored');f.c.config.countNoCoverage=false;assert.equal(m.normalize([...raw('KILLED'),...raw('NO_COVERAGE',3)],f.c,target).score,1);});
test('Kotlin filter does not discard Java or arbitrary suspend logic',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0];let r=m.normalize([{...raw()[0],file:'Foo.kt',method:'foo$default'}, {...raw()[0],file:'Foo.java',method:'foo$default'}, {...raw()[0],file:'Foo.kt',method:'invokeSuspend'}],f.c,target);assert.equal(r.filtered_junk,1);assert.equal(r.survived,2);});
test('report cap is 1800 characters, factual and ranked',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],r=m.normalize(Array.from({length:100},(_,n)=>({...raw()[0],line:n+1,description:'long factual description '.repeat(20)})),f.c,target);const text=m.report(r);assert.ok(text.length<=1800);assert.match(text,/survivors shown of 100/);assert.match(text,/Playbook:/);});
test('report collapses identical survivor lines and states the no-weakening rule',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],r=m.normalize([...[1,2,3,4].map(k=>({...raw('NO_COVERAGE',36)[0],mutation_key:String(k)})),...raw('SURVIVED',7)],f.c,target);const text=m.report(r),lines=text.split('\n').filter(l=>l.startsWith('src/'));assert.equal(lines.length,2,text);assert.ok(lines.some(l=>l.endsWith(' ×4')),text);assert.match(text,/5 survivors shown of 5/);assert.match(text,/don't weaken reachable code/);});
test('passing report has no footer and joined reports state the rule once, last, within the cap',t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],rule=/^Kill survivors/,count=s=>s.split('\n').filter(l=>rule.test(l)).length;assert.doesNotMatch(m.report(m.normalize(raw('KILLED'),f.c,target)),/Kill survivors/);const one=m.report(m.normalize(raw(),f.c,target)),long=m.report(m.normalize(Array.from({length:100},(_,n)=>({...raw()[0],line:n+1,description:'long factual description '.repeat(20)})),f.c,target));for(const [text,max] of [[m.joinReports([one,one]),Infinity],[m.joinReports([long,long,long],1800),1800]]){assert.ok(text.length<=max);assert.equal(count(text),1,text);assert.match(text.split('\n').at(-1),rule);}assert.doesNotMatch(m.joinReports([m.report(m.normalize(raw('KILLED'),f.c,target)),'x']),/Kill survivors/);});
test('gate with two below-threshold targets states the rule once, last, in report and reason',async t=>{const f=fixture(t);for(const n of ['Foo','Bar']){f.put(`src/main/java/acme/${n}.java`,`package acme; public class ${n} {}`);f.put(`src/test/java/acme/${n}Test.java`,`package acme; public class ${n}Test {}`);await m.register(f.c,`src/test/java/acme/${n}Test.java`);}for(const n of ['Foo','Bar'])await m.runTarget(f.c,m.hash('acme.'+n),async()=>({raw:raw().map(x=>({...x,file:n+'.java',class:'acme.'+n}))}));const g=await m.gate(f.c,{hook:true});for(const text of [g.report,g.reason]){assert.match(text,/acme\.Bar score/);assert.match(text,/acme\.Foo score/);assert.equal(text.split('\n').filter(l=>/^Kill survivors/.test(l)).length,1,text);assert.match(text.split('\n').at(-1),/^Kill survivors/);}});
test('gate CLI report is not cut off before a below-threshold target listed last',async t=>{const f=fixture(t),long=Array.from({length:10},(_,n)=>({...raw('SURVIVED',n+1)[0],method:'longMethodName'.repeat(20)})),killed=Array.from({length:50},(_,n)=>raw('KILLED',n+20)[0]);for(const n of ['A','B','Bar']){f.put(`src/main/java/acme/${n}.java`,`package acme; public class ${n} {}`);f.put(`src/test/java/acme/${n}Test.java`,`package acme; public class ${n}Test {}`);await m.register(f.c,`src/test/java/acme/${n}Test.java`);}for(const n of ['A','B','Bar'])await m.runTarget(f.c,m.hash('acme.'+n),async()=>({raw:n==='Bar'?raw():[...long,...killed]}));const text=(await m.gate(f.c)).report;assert.match(text,/mutagate: acme\.A score 0\.83/);assert.match(text,/mutagate: acme\.Bar score 0\.00/);});
test('unresolved warnings for deleted test files are dropped from status and gate',async t=>{const f=await scored(t),gone='mutagate: target unresolved for src/test/java/acme/GoneTest.java. Candidates: none. Select with mutagate run src/test/java/acme/GoneTest.java --target <target>.',kept=`mutagate: target unresolved for ${f.test}. Candidates: none. Select with mutagate run ${f.test} --target <target>.`;await m.updateState(f.c,s=>{s.warnings=[gone,kept];});for(const text of [m.status(f.c),(await m.gate(f.c)).report]){assert.ok(!text.includes('GoneTest'),text);assert.ok(text.includes(kept),text);}});
test('low quality blocks twice, including stop_hook_active, then warns',async t=>{const {c}=await scored(t);for(let n=0;n<2;n++){const r=await m.handleHook(c,{stop_hook_active:true},'Stop');assert.equal(r.code,2);assert.equal(r.out.decision,'block');}const r=await m.handleHook(c,{},'Stop');assert.equal(r.code,0);assert.match(r.out.systemMessage,/round cap/);assert.equal((await m.gate(c)).code,1);});
test('pass allows and infrastructure errors fail open',async t=>{const f=await scored(t,'KILLED');assert.equal((await m.handleHook(f.c,{},'Stop')).code,0);f.put(f.source,'changed');const jdk=async()=>{throw Error('missing JDK');};await m.runTarget(f.c,f.key,jdk);await m.runTarget(f.c,f.key,jdk);const r=await m.handleHook(f.c,{},'Stop');assert.equal(r.code,0);assert.match(r.out.systemMessage,/missing JDK/);});
test('advise mode never blocks',async t=>{const {c}=await scored(t,'SURVIVED',{mode:'advise'});assert.equal((await m.handleHook(c,{},'Stop')).code,0);});
test('pending results block once then allow with warning',async t=>{const f=fixture(t,{gateBudgetSec:0});await m.register(f.c,f.test);assert.equal((await m.handleHook(f.c,{},'Stop')).code,2);assert.equal((await m.handleHook(f.c,{},'Stop')).code,0);});
test('waivers rescore fresh results and line changes invalidate IDs',async t=>{const f=await scored(t),r=m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]);f.put('.mutagate/waivers.json',JSON.stringify({schema:1,waivers:[{id:r.survivors[0].id,target:'acme.Foo',reason:'equivalent'}]}));assert.equal(m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]).score,1);await m.runTarget(f.c,f.key,async()=>({raw:raw('SURVIVED',2)}));assert.match(m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]).warnings[0],/no longer matches/);});
test('invalid waivers.json counts as no waivers with one warning and Stop still blocks',async t=>{const f=await scored(t);for(const bad of ['{"waivers": [ }','{"waivers":{}}','{"waivers":[{"id":"x","reason":5}]}','{"waivers":[{"id":"x","target":"acme.Foo"}]}']){f.put('.mutagate/waivers.json',bad);const r=m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]);assert.equal(r.survived,1);assert.equal(r.warnings.filter(w=>/waivers\.json/.test(w)).length,1,bad);const x=m.report(r);assert.equal(m.joinReports([x,x,x]).split('waivers.json is invalid').length,2,'one line for several targets');}const g=await m.handleHook(f.c,{},'Stop');assert.equal(g.code,2);assert.match(g.out.reason,/waivers\.json is invalid/);});
test('corrupt result JSON reruns and corrupt state reads blank with a note',async t=>{const f=await scored(t);fs.writeFileSync(path.join(f.c.data,'results',f.c.session,f.key+'.json'),'{"sch');assert.equal(m.loadResult(f.c,f.key,m.state(f.c).targets[f.key]),null);let runs=0;const g=await m.gate(f.c,{runner:async()=>(runs++,{raw:raw()})});assert.equal(runs,1);assert.equal(g.code,1);assert.match(g.report,/score 0\.00/);const note=t.mock.method(process.stderr,'write',()=>true);fs.writeFileSync(f.c.stateFile,'');assert.deepEqual(m.state(f.c).targets,{});assert.match(String(note.mock.calls[0]?.arguments[0]),/session state .* is not valid JSON; it starts blank/);m.state(f.c);assert.equal(note.mock.calls.length,1);await m.updateState(f.c,s=>{s.x=1;});assert.equal(m.state(f.c).x,1);});
test('an exception in one target skips it with a warning and still gates the others',async t=>{const f=fixture(t);for(const n of ['Foo','Bar']){f.put(`src/main/java/acme/${n}.java`,`package acme; public class ${n} {}`);f.put(`src/test/java/acme/${n}Test.java`,`package acme; public class ${n}Test {}`);await m.register(f.c,`src/test/java/acme/${n}Test.java`);}const run=(n,status)=>m.runTarget(f.c,m.hash('acme.'+n),async()=>({raw:raw(status).map(x=>({...x,file:n+'.java',class:'acme.'+n}))}));await run('Foo');await run('Bar');fs.writeFileSync(path.join(f.c.data,'results',f.c.session,m.hash('acme.Foo')+'.json'),'{"raw":5}');const trace=process.env.MUTAGATE_TRACE;t.after(()=>{if(trace===undefined)delete process.env.MUTAGATE_TRACE;else process.env.MUTAGATE_TRACE=trace;});process.env.MUTAGATE_TRACE='1';let g=await m.gate(f.c);assert.equal(g.code,1);assert.match(g.report,/mutagate: acme\.Foo skipped: /);assert.ok(fs.readFileSync(path.join(f.c.data,'trace.jsonl'),'utf8').split('\n').filter(Boolean).map(JSON.parse).some(e=>e.event==='Result'&&e.target==='acme.Foo'&&e.decision==='skipped'&&e.error));assert.match(g.report,/acme\.Bar score 0\.00/);assert.equal((await m.handleHook(f.c,{},'Stop')).code,2);await run('Bar','KILLED');g=await m.gate(f.c);assert.equal(g.code,3);const res=n=>path.join(f.c.data,'results',f.c.session,m.hash('acme.'+n)+'.json');fs.rmSync(res('Foo'));await run('Foo');fs.writeFileSync(res('Bar'),'{"raw":5}');g=await m.gate(f.c);assert.match(g.report,/mutagate: acme\.Bar skipped: /);assert.equal(g.code,1,'a skip after a below-threshold target keeps exit 1');});
test('a corrupt PIT classpath cache reads as missing and the classpath is resolved again',async t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],home=path.join(f.c.repo,'jdk'),oldHome=process.env.JAVA_HOME;t.after(()=>{if(oldHome===undefined)delete process.env.JAVA_HOME;else process.env.JAVA_HOME=oldHome;});f.put('jdk/bin/java',`#!${process.execPath}\nprocess.stderr.write('openjdk version "21"\\n');`);fs.chmodSync(path.join(home,'bin/java'),0o755);f.put('gradlew',`#!${process.execPath}\nrequire('node:fs').writeFileSync(${JSON.stringify(path.join(f.c.repo,'gradle-ran'))},'');`);fs.chmodSync(path.join(f.c.repo,'gradlew'),0o755);process.env.JAVA_HOME=home;const cp=path.join(f.c.data,'classpath',m.hash(path.resolve(f.c.repo,target.module))+'.json');fs.mkdirSync(path.dirname(cp),{recursive:true});fs.writeFileSync(cp,'{"hash":"');const dir=fs.mkdtempSync(path.join(f.c.repo,'run-'));await assert.rejects(m.runners().pit(f.c,{...target,tests:[f.test],testNames:[]},dir,{cwd:f.c.repo,timeout:30000,deadline:Date.now()+30000}),/Gradle classpath task returned no data/);assert.ok(fs.existsSync(path.join(f.c.repo,'gradle-ran')));});
test('PIT hashes an unreadable build file as empty',{skip:process.platform==='win32'||process.getuid?.()===0},async t=>{const f=fixture(t),home=path.join(f.c.repo,'jdk'),oldHome=process.env.JAVA_HOME;t.after(()=>{if(oldHome===undefined)delete process.env.JAVA_HOME;else process.env.JAVA_HOME=oldHome;});f.put('gradle.properties','org.gradle.jvmargs=-Xmx1g');fs.chmodSync(path.join(f.c.repo,'gradle.properties'),0);const target=m.resolveTargets(f.c,f.test).targets[0];f.put('jdk/bin/java',`#!${process.execPath}\nprocess.stderr.write('openjdk version "21"\\n');`);fs.chmodSync(path.join(home,'bin/java'),0o755);f.put('gradlew',`#!${process.execPath}\n`);fs.chmodSync(path.join(f.c.repo,'gradlew'),0o755);process.env.JAVA_HOME=home;const dir=fs.mkdtempSync(path.join(f.c.repo,'run-'));await assert.rejects(m.runners().pit(f.c,{...target,tests:[f.test],testNames:[]},dir,{cwd:f.c.repo,timeout:30000,deadline:Date.now()+30000}),/Gradle classpath task returned no data/);});
test('a Gradle compile waits for the repo-wide JVM compile lock (Maven uses the same helper), released after the compile',async t=>{const f=fixture(t),target=m.resolveTargets(f.c,f.test).targets[0],home=path.join(f.c.repo,'jdk'),oldHome=process.env.JAVA_HOME,ran=path.join(f.c.repo,'gradle-ran'),held=path.join(f.c.data,'locks','jvm-compile.lock');t.after(()=>{if(oldHome===undefined)delete process.env.JAVA_HOME;else process.env.JAVA_HOME=oldHome;});f.put('jdk/bin/java',`#!${process.execPath}\nprocess.stderr.write('openjdk version "21"\\n');`);fs.chmodSync(path.join(home,'bin/java'),0o755);f.put('gradlew',`#!${process.execPath}\nrequire('node:fs').writeFileSync(${JSON.stringify(ran)},'');`);fs.chmodSync(path.join(f.c.repo,'gradlew'),0o755);process.env.JAVA_HOME=home;const pit=ms=>m.runners().pit(f.c,{...target,tests:[f.test],testNames:[]},fs.mkdtempSync(path.join(f.c.repo,'run-')),{cwd:f.c.repo,timeout:30000,deadline:Date.now()+ms});fs.mkdirSync(path.dirname(held),{recursive:true});fs.writeFileSync(held,JSON.stringify({pid:process.pid,token:'other'}));await assert.rejects(pit(1000),/budget exceeded waiting for another Maven or Gradle compile/);assert.equal(fs.existsSync(ran),false);fs.rmSync(held);await assert.rejects(pit(30000),/Gradle classpath task returned no data/);assert.ok(fs.existsSync(ran));assert.equal(fs.existsSync(held),false);});
test('loadResult keeps the runner of a stored result',async t=>{const f=fixture(t);await m.register(f.c,f.test);const key=m.hash('acme.Foo');await m.runTarget(f.c,key,async()=>({raw:raw(),runner:'gremlins'}));assert.equal(m.loadResult(f.c,key,m.state(f.c).targets[key]).runner,'gremlins');assert.equal(JSON.parse(m.status(f.c,true))[0].result.runner,'gremlins');});
test('target verdict classifies a target, its obligation and one exit code for gate and run --sync',async t=>{const f=fixture(t),key='k',r=(status,x={})=>({target:'acme.Foo',status,score:null,survivors:[],...x}),v=x=>{const {kind,code,obligation,once}=m.verdict(f.c,key,undefined,x);return [kind,code,obligation,once];};assert.deepEqual(v(null),['pending',1,'block','pendingBlocked']);assert.deepEqual(v(r('unscored',{tests_deleted:true,error:'its registered tests were deleted'})),['unscored',1,'block','pendingBlocked']);assert.deepEqual(v(r('unscored',{error:`${m.NO_MUTANTS} in Foo.java`})),['unscored',0,'none',undefined]);assert.deepEqual(v(r('unscored',{error:'every mutant errored'})),['unscored',1,'warn',undefined]);assert.deepEqual(v(r('error',{agent_caused:true})),['retry',3,'block','errorBlocked']);assert.deepEqual(v(r('error',{attempts:2})),['error',3,'warn',undefined]);assert.deepEqual(v(r('below',{score:0.5})),['below',1,'block',undefined]);assert.deepEqual(v(r('pass',{score:1})),['pass',0,'none',undefined]);assert.equal(m.verdict(f.c,key,undefined).kind,'pending');assert.equal(m.verdict(f.c,key,undefined,null).running,false);fs.mkdirSync(path.join(f.c.data,'locks'),{recursive:true});fs.writeFileSync(path.join(f.c.data,'locks',key+'.lock'),JSON.stringify({pid:process.pid,token:'t'}));assert.equal(m.verdict(f.c,key,undefined,null).running,true);const fold=(...xs)=>xs.reduce((code,x)=>m.exitCode(code,m.verdict(f.c,key,undefined,x)),0);assert.equal(fold(r('error',{attempts:2}),null),3);assert.equal(fold(null,r('error',{attempts:2})),1);assert.equal(fold(r('error',{attempts:2}),r('below',{score:0.5})),1);assert.equal(fold(r('pass',{score:1}),r('unscored',{error:`${m.NO_MUTANTS} in Foo.java`})),0);});
