test('install is idempotent and uninstall preserves unrelated hooks',t=>{const f=fixture(t);f.put('.claude/settings.json',JSON.stringify({permissions:{allow:['Read']},hooks:{Stop:[{hooks:[{type:'command',command:'echo retained'}]}]}}));m.install(f.c,'claude');const once=fs.readFileSync(path.join(f.c.repo,'.claude/settings.json'),'utf8');m.install(f.c,'claude');assert.equal(fs.readFileSync(path.join(f.c.repo,'.claude/settings.json'),'utf8'),once);m.install(f.c,'claude','project',true);const out=JSON.parse(fs.readFileSync(path.join(f.c.repo,'.claude/settings.json')));assert.equal(out.hooks.Stop[0].hooks[0].command,'echo retained');assert.deepEqual(out.permissions,{allow:['Read']});});
