test('a lock is abandoned when its pid is dead or after 60 s without heartbeat, one waiter takes it over through .break (a live pid only after watching its mtime unchanged), its holder heartbeats, and only its token releases it',async t=>{const {c,key}=await scored(t),p=c.stateFile+'.lock',tl=path.join(c.data,'locks',key+'.lock'),old=new Date(Date.now()-61000),gone=spawnSync(process.execPath,['-e','']).pid,put=(f,token,pid=process.pid)=>{fs.mkdirSync(path.dirname(f),{recursive:true});fs.writeFileSync(f,JSON.stringify({pid,token}));},token=f=>JSON.parse(fs.readFileSync(f)).token,running=()=>JSON.parse(m.status(c,true))[0].in_flight;put(tl,'run');assert.equal(running(),true);const mid=new Date(Date.now()-50000);fs.utimesSync(tl,mid,mid);assert.equal(running(),true);fs.utimesSync(tl,old,old);assert.equal(running(),false);put(tl,'dead',gone);assert.equal(running(),false);put(p,'dead',gone);t.mock.timers.enable({apis:['setInterval']});const t0=Date.now();await m.updateState(c,s=>{s.choices.a=1;fs.utimesSync(p,old,old);t.mock.timers.tick(10000);assert.ok(Date.now()-fs.statSync(p).mtimeMs<5000);put(p,'thief');});assert.ok(Date.now()-t0<2000);assert.equal(token(p),'thief');assert.equal(m.state(c).choices.a,1);put(tl,'old');fs.utimesSync(tl,old,old);c.budgetSec=.2;setTimeout(()=>{const n=new Date();fs.utimesSync(tl,n,n);},30);assert.equal(await m.runTarget(c,key),null);assert.equal(token(tl),'old');fs.utimesSync(tl,old,old);put(tl+'.break','breaker');c.budgetSec=.05;assert.equal(await m.runTarget(c,key),null);assert.equal(token(tl),'old');fs.rmSync(tl+'.break');assert.ok(await m.runTarget(c,key));assert.equal(fs.existsSync(tl),false);});
test('after taking .break a waiter re-checks the token and the heartbeat, and its watch of a live pid restarts when the mtime moves',async t=>{const {c,key}=await scored(t),tl=path.join(c.data,'locks',key+'.lock'),br=tl+'.break',gone=spawnSync(process.execPath,['-e','']).pid,put=(f,token,pid=process.pid,ago=0)=>{fs.writeFileSync(f,JSON.stringify({pid,token}));const d=new Date(Date.now()-ago);fs.utimesSync(f,d,d);},token=()=>JSON.parse(fs.readFileSync(tl)).token,open=fs.openSync,run=hook=>{const mk=t.mock.method(fs,'openSync',(f,...a)=>{if(a[0]==='wx')hook(f);return open(f,...a);});c.budgetSec=.2;return m.runTarget(c,key,async()=>({raw:raw()})).finally(()=>mk.mock.restore());};let n=0;put(tl,'dead',gone);assert.equal(await run(f=>{if(f===br&&!n++)put(tl,'new',process.pid,61000);else if(f===br)put(br,'breaker');}),null);assert.equal(token(),'new');fs.rmSync(br);n=0;put(tl,'old',process.pid,61000);assert.equal(await run(f=>{if(f===br&&!n++){const d=new Date();fs.utimesSync(tl,d,d);}}),null);assert.equal(token(),'old');assert.equal(n,1);put(tl,'old',process.pid,61000);assert.equal(await run(f=>{if(f===tl){const d=new Date(fs.statSync(tl).mtimeMs-1000);fs.utimesSync(tl,d,d);}}),null);assert.equal(token(),'old');});
