test('mutation-testing-elements paths, identities and statuses normalize across tools',t=>{const {c,put}=fixture(t);put('mod/foo.go','package foo');const mutant={location:{start:{line:2,column:1},end:{line:2,column:3}},replacement:'0',mutatorName:'RETURN_ZERO'};for(const [key,root] of [[path.join(c.repo,'mod/foo.go'),'/irrelevant'],['foo.go',path.join(c.repo,'mod')],['mod/foo.go',undefined]]){const r=m.parseMutationTestingElements({projectRoot:root,files:{[key]:{mutants:['Killed','Survived','Timeout','NoCoverage','CompileError','RuntimeError','Ignored','Pending','Future'].map(status=>({...mutant,status}))}}},c.repo);assert.ok(r.every(x=>x.file==='mod/foo.go'));assert.deepEqual(r.map(x=>x.status),['KILLED','SURVIVED','TIMED_OUT','NO_COVERAGE','NON_VIABLE','RUN_ERROR','NON_VIABLE','PENDING','PENDING']);assert.equal(r[0].mutation_key,JSON.stringify([mutant.location,'0']));}assert.throws(()=>m.parseMutationTestingElements({},c.repo),/invalid/);});
test('mutation-testing-elements survivors show the replaced source text',t=>{const {c,put,test:tf}=fixture(t);put('mod/max.go','package foo\nconst Max = 1000\nvar é = 1000\n');const plain=(line,start,end,replacement='999')=>m.plainMutation(m.parseMutationTestingElements({files:{'mod/max.go':{mutants:[{location:{start:{line,column:start},end:{line:end[0],column:end[1]}},replacement,mutatorName:'INTEGER_DECREMENT',status:'Survived'}]}}},c.repo)[0],c);assert.equal(plain(2,13,[2,17]),'1000 became 999 and no test noticed');for(const x of [plain(2,13,[3,5]),plain(3,9,[3,13]),plain(2,13,[2,17],'9\n9'),plain(2,13,[2,17],' 999'),m.plainMutation({file:'mod/max.go',line:2,mutator:'INTEGER_DECREMENT',mutation_key:'not json'},c)])assert.equal(x,'increment changed and no test noticed');assert.equal(m.plainMutation({file:'mod/max.go',line:2,mutator:'BRANCH_IF',mutation_key:'not json'},c),'call or block removed and no test noticed');assert.equal(m.plainMutation({file:'mod/max.go',line:2,mutator:'ERRORF_WRAP',mutation_key:'not json'},c),'error wrapping (%w) dropped and no test noticed');const short=mutator=>m.normalize([{...raw()[0],mutator}],c,m.resolveTargets(c,tf).targets[0]).survivors[0].short;assert.deepEqual(['BRANCH_IF','EXPRESSION_REMOVE','ERRORF_WRAP'].map(short),['void-call','conditional','error-wrap']);});
test('gremlins parses spaced statuses and package-relative paths',()=>{const r=m.runners().parseGremlins({files:[{file_name:'foo.go',mutations:['NOT COVERED','LIVED','TIMED OUT','KILLED','NOT VIABLE','SKIPPED','RUNNABLE','Future'].map(status=>({line:3,column:7,type:'CONDITIONALS_BOUNDARY',status}))}]},'mod/pkg');assert.ok(r.every(x=>x.file==='mod/pkg/foo.go'));assert.deepEqual(r.map(x=>x.status),['NO_COVERAGE','SURVIVED','TIMED_OUT','KILLED','NON_VIABLE','NON_VIABLE','PENDING','PENDING']);assert.throws(()=>m.runners().parseGremlins({},''),/invalid/);});
test('C# fingerprints follow transitive references and ignore tool and build output',t=>{const {c,put}=fixture(t);c.root=path.join(c.repo,'cache-root');put('Acme.Tests/Acme.Tests.csproj','<Project><ProjectReference Include="../Acme/Acme.csproj"/></Project>');put('Acme.Tests/PricingTests.cs','class PricingTests {}');put('Acme/Acme.csproj',"<Project><ProjectReference Include='../Shared/Shared.csproj'/></Project>");put('Acme/Pricing.cs','class Pricing {}');put('Shared/Shared.csproj','<Project><ProjectReference Include="../Acme/Acme.csproj"/></Project>');put('Shared/Value.cs','class Value {}');put('Directory.Build.props','<Project/>');put('Acme.sln','solution');const target=m.resolveTargets(c,'Acme.Tests/PricingTests.cs').targets[0],files=inputFiles(c,target),before=m.fingerprint(c,target);for(const file of ['Shared/Value.cs','Acme/Pricing.cs','Acme.Tests/Acme.Tests.csproj','Directory.Build.props','Acme.sln'])assert.ok(files.includes(file),file);for(const file of ['Acme/obj/project.assets.json','Acme/bin/a.dll','cache-root/tools/dotnet-stryker','Acme/StrykerOutput/report.json','Acme/TestResults/report.xml'])put(file,'output');assert.equal(m.fingerprint(c,target),before);put('Shared/Value.cs','class Value { int n; }');assert.notEqual(m.fingerprint(c,target),before);});
