test('runner process trees die when mutagate gets a signal or exits',{skip:process.platform==='win32'},async t=>{const {c}=fixture(t),alive=p=>{try{process.kill(p,0);return true;}catch{return false;}},pids=[];t.after(()=>{for(const p of pids)try{process.kill(p,'SIGKILL');}catch{}});const tree=`const g=require('node:child_process').spawn(process.execPath,['-e','setInterval(()=>{},1e3)'],{stdio:'ignore'});require('node:fs').writeFileSync(process.argv[1],process.pid+' '+g.pid);setInterval(()=>{},1e3)`;for(const [how,code] of [['SIGINT',130],['SIGTERM',143],['SIGHUP',129],['exit',0]]){const file=path.join(c.repo,how),parent=spawn(process.execPath,['--input-type=module','-e',`const m=await import(${JSON.stringify(new URL('../scripts/mutagate.mjs',import.meta.url).href)}),fs=await import('node:fs');m.runners().command(process.execPath,['-e',${JSON.stringify(tree)},${JSON.stringify(file)}],{timeout:60000});${how==='exit'?`setInterval(()=>{if(/ /.test(fs.readFileSync(${JSON.stringify(file)},{encoding:'utf8',flag:'a+'})))process.exit(0);},20);`:''}`],{stdio:'ignore'}),exited=new Promise(r=>parent.on('exit',r));let ids=[];for(let i=0;i<250&&ids.length<2;i++){await new Promise(r=>setTimeout(r,20));try{ids=fs.readFileSync(file,'utf8').trim().split(' ').filter(Boolean).map(Number);}catch{}}pids.push(...ids);assert.equal(ids.length,2,how);if(how!=='exit')parent.kill(how);const got=await exited;for(let i=0;i<150&&ids.some(alive);i++)await new Promise(r=>setTimeout(r,20));assert.deepEqual([got,...ids.map(alive)],[code,false,false],how);}});
