test('JUnit launcher resolves beside the engine jar or fails naming coordinates',async t=>{const {c,put}=fixture(t);const jar=a=>`m2/org/junit/platform/junit-platform-${a}/6.0.3/junit-platform-${a}-6.0.3.jar`,engine=path.join(c.repo,jar('engine')),calls=path.join(c.repo,'calls'),jup='/x/junit-jupiter-api-6.0.3.jar';put(jar('engine'),'');put(jar('launcher'),'');assert.equal(await m.runners().launcherJar([engine,jup],null,{}),path.join(c.repo,jar('launcher')));assert.equal(await m.runners().launcherJar([engine,jup,'/x/junit-platform-launcher-6.0.3.jar'],null,{}),null);assert.equal(await m.runners().launcherJar([engine],null,{}),null);assert.equal(await m.runners().launcherJar(['/x/junit-4.13.2.jar'],null,{}),null);fs.unlinkSync(path.join(c.repo,jar('launcher')));put('mvnw',`#!${process.execPath}\nrequire('node:fs').writeFileSync(${JSON.stringify(calls)},process.argv.slice(2).join(' '));`);fs.chmodSync(path.join(c.repo,'mvnw'),0o755);await assert.rejects(m.runners().launcherJar([engine,jup],path.join(c.repo,'mvnw'),{}),/junit-platform-launcher:6\.0\.3/);assert.match(fs.readFileSync(calls,'utf8'),/dependency:get .*junit-platform-launcher:6\.0\.3 -Dtransitive=false/);await assert.rejects(m.runners().launcherJar([engine,jup],null,{}),/junit-platform-launcher:6\.0\.3/);});
test('failed commands name the cause and runs keep a truncated per-target log',async t=>{await assert.rejects(m.runners().command(process.execPath,['-e','console.error("VM : x\\njava.lang.NoClassDefFoundError: org/junit/x\\n\\tat a.b(C.java:1)\\nInput ->");process.exit(1)']),e=>/NoClassDefFoundError/.test(e.message)&&!/\tat |Input ->/.test(e.message));await assert.rejects(m.runners().command(process.execPath,['-e','console.log("[ERROR] /a/Foo.java:[3,1] cannot find symbol\\n/a/Foo.java:3: error: cannot find symbol\\nFAILURE: Build failed with an exception.\\nExecution failed for task :compileJava.\\n> Compilation failed; see the compiler error output for details.\\nBUILD FAILED in 1s\\n[ERROR] \\n[ERROR] -> [Help 1]\\n[ERROR] Re-run Maven using the -X switch\\n[ERROR] For more information about the errors\\n[ERROR] [Help 1] http://x/CompilationFailureException");process.exit(1)']),e=>/cannot find symbol \| .*cannot find symbol$/.test(e.message)&&!/Help|FAILURE|BUILD|Execution|Compilation failed/.test(e.message));await assert.rejects(m.runners().command(process.execPath,['-e','console.error("FAILURE: Build failed with an exception.\\n\\n* What went wrong:\\nExecution failed for task :compileTestJava.\\n> Could not find org.junit.jupiter:junit-jupiter:9.9.9.\\n\\n* Try:\\n> Run with --stacktrace option to get the stack trace.\\n\\nBUILD FAILED in 2s");process.exit(1)']),/failed \(1\): > Could not find org\.junit\.jupiter:junit-jupiter:9\.9\.9\.$/);const f=fixture(t);await m.register(f.c,f.test);for(let n=0;n<2;n++){const r=await m.runTarget(f.c,m.hash('acme.Foo'),async(c,t,dir,opts)=>{fs.appendFileSync(opts.log,'line\n');throw Error('boom');});assert.match(r.error,/^boom; log: /);assert.equal(fs.readFileSync(r.error.split('; log: ')[1],'utf8'),'line\n');}});
