test('the async handler starts only targets whose last run fits before its 850 s deadline; a run cut at a deadline stays pending',async t=>{const f=fixture(t),key=n=>m.hash('acme.'+n),ran=[];for(const n of 'ABCD'){f.put(`src/main/java/acme/${n}.java`,`package acme; class ${n} {}`);f.put(`src/test/java/acme/${n}Test.java`,`package acme; class ${n}Test {}`);await m.register(f.c,`src/test/java/acme/${n}Test.java`);}await m.updateState(f.c,s=>{for(const n of 'ABC')s.targets[key(n)].lastRunMs=400000;});let now=Date.now();const t0=now,cut=async()=>{throw Error('SIGKILL');},runner=async(c,x,dir,opts)=>{ran.push([x.target,opts.timeout,opts.deadline-t0]);if(x.target==='acme.D'){now=opts.deadline;return cut();}now+=400000;return {raw:[]};},post=mutate=>m.handleHook({...f.c,args:mutate?{mutate:true}:{},runner},{tool_use_id:'a',tool_input:{file_path:'src/test/java/acme/ATest.java'}},'PostToolUse');await post();await m.updateState(f.c,s=>{s.editedAt=0;});t.mock.method(Date,'now',()=>now);await post(true);assert.deepEqual(ran,[['acme.A',300000,300000],['acme.B',300000,700000],['acme.D',50000,850000]]);assert.equal(m.hookConfig('claude').hooks.PostToolUse[0].hooks[1].timeout*1000-50000,850000,'deadline = async hook timeout - 50 s');const pending=n=>m.loadResult(f.c,key(n),m.state(f.c).targets[key(n)])===null;assert.ok(pending('C')&&pending('D'));assert.equal(await m.runTarget({...f.c,deadline:now+60000},key('C'),cut),null);assert.ok(pending('C'));});
test('a backward clock jump stretches neither the async quiet wait past 6 s nor the worker delay past 3 s',async t=>{const f=await scored(t,'KILLED'),post=mutate=>m.handleHook({...f.c,args:mutate?{mutate:true}:{}},{tool_use_id:'a',tool_input:{file_path:f.test}},'PostToolUse');await post();await m.updateState(f.c,s=>{s.editedAt=Date.now()+3600e3;});sessionEnv(t,{MUTAGATE_HOOK_SESSION:'w'});const old=process.env.CLAUDE_PLUGIN_DATA;t.after(()=>{if(old===undefined)delete process.env.CLAUDE_PLUGIN_DATA;else process.env.CLAUDE_PLUGIN_DATA=old;});process.env.CLAUDE_PLUGIN_DATA=f.c.root;await m.updateState(m.context({repo:f.c.repo}),s=>{s.targets.k={file:'gone.java',changedAt:Date.now()+3600e3};});t.mock.timers.enable({apis:['setTimeout']});const ends=async(p,ms)=>{let done=false;p.then(()=>{done=true;});for(let i=0;i<=ms/1000&&!done;i++){await new Promise(r=>setImmediate(r));t.mock.timers.tick(1000);}await new Promise(r=>setImmediate(r));return done;};assert.ok(await ends(post(true),6000),'quiet wait');assert.ok(await ends(m.main(['worker','--repo',f.c.repo,'--key','k']),9000),'worker delay');});
test('async mutation handler waits for a build running in the repo',{skip:process.platform==='win32'},async t=>{const f=await scored(t,'KILLED');const build=spawn(process.execPath,['-e','setTimeout(()=>{},30000)','org.codehaus.plexus.classworlds.launcher.Launcher',`-Dmaven.multiModuleProjectDirectory=${f.c.repo}`]);t.after(()=>build.kill());await new Promise(r=>setTimeout(r,300));assert.equal(m.buildRunning(f.c),true);assert.equal(m.buildRunning({repo:f.c.repo.slice(0,-1)}),false);await m.handleHook(f.c,{tool_use_id:'a',tool_input:{file_path:f.test}},'PostToolUse');await m.updateState(f.c,s=>{s.editedAt=0;});f.put(f.source,'package acme; public class Foo { public int price(int n) { return n > 5 ? 10 : 20; }}');const started=Date.now(),hook=m.handleHook({...f.c,args:{mutate:true}},{tool_use_id:'a',tool_input:{file_path:f.test}},'PostToolUse');await new Promise(r=>setTimeout(r,1500));await m.runTarget(f.c,f.key,async()=>({raw:raw('KILLED')}));build.kill();assert.deepEqual(await hook,{code:0});assert.ok(Date.now()-started>=1500);});
