test('production edits no target mutates are noted in check and status, never in the gate',async t=>{const f=fixture(t);for(const x of ['internal/rest/ctrl.go','web/x.html','x_gen.go','gone.go','vitest.config.ts','X.Tests/Usings.cs','X.Tests/Support.cs','jest.setup.js'])f.put(x,'package x');f.put('X.Tests/X.Tests.csproj','<Project><PackageReference Include="xunit"/></Project>');const post=(id,mutate)=>m.handleHook({...f.c,args:mutate?{mutate:true}:{}},{tool_use_id:id,tool_name:'Write',tool_input:{file_path:path.join(f.c.repo,id)}},'PostToolUse');await post('internal/rest/ctrl.go');assert.deepEqual(m.state(f.c).edited,['internal/rest/ctrl.go']);await post('gone.go',true);assert.deepEqual(m.state(f.c).edited,['internal/rest/ctrl.go']);for(const x of ['web/x.html','x_gen.go','gone.go','vitest.config.ts','X.Tests/Usings.cs','X.Tests/Support.cs','jest.setup.js',f.source])await post(x);assert.ok(!m.state(f.c).edited.some(x=>/config|Usings|setup/.test(x)));await m.updateState(f.c,s=>{s.edited.push('vitest.config.ts','X.Tests/Usings.cs');});fs.rmSync(path.join(f.c.repo,'gone.go'));await m.register(f.c,f.test);await m.runTarget(f.c,m.hash('acme.Foo'),async()=>({raw:raw('KILLED')}));const g=await m.gate(f.c),note='mutagate: not mutation-tested, no test targets them: internal/rest/ctrl.go. Write tests for them to gate them.';assert.equal(g.report.split('\n').at(-1),note);assert.ok(m.status(f.c).endsWith('\n'+note),m.status(f.c));assert.deepEqual(await m.handleHook(f.c,{},'Stop'),{code:0});await m.updateState(f.c,s=>{s.edited=[];});const plain=await m.gate(f.c);assert.equal(g.code,plain.code);assert.equal(g.report,plain.report+'\n'+note);assert.ok(!plain.report.includes('not mutation-tested'));});
test('untargeted note lists at most eight files',async t=>{const f=fixture(t),files=[...Array(10)].map((_,i)=>`p/f${i}.go`);for(const x of files)f.put(x,'package p');await m.register(f.c,f.test);await m.runTarget(f.c,m.hash('acme.Foo'),async()=>({raw:raw()}));await m.updateState(f.c,s=>{s.edited=files;});const g=await m.gate(f.c),line=g.report.split('\n').find(l=>l.includes('not mutation-tested'));assert.equal(g.code,1);assert.equal(line,`mutagate: not mutation-tested, no test targets them: ${files.slice(0,8).join(', ')} (+2 more). Write tests for them to gate them.`);assert.match(g.report.split('\n').at(-1),/^Kill survivors/);assert.ok(!g.reason.includes('not mutation-tested'));});
