test('JVM test with a suffix after the class name resolves to the longest class prefixing its stem, ties stay unresolved',t=>{const {c,put}=fixture(t);put('src/main/java/acme/Matrix.java','package acme; public class Matrix {}');put('src/main/java/acme/MatrixService.java','package acme; public class MatrixService {}');put('src/test/java/acme/MatrixServiceSmokeTest.java','package acme; class MatrixServiceSmokeTest {}');const r=m.resolveTargets(c,'src/test/java/acme/MatrixServiceSmokeTest.java');assert.deepEqual(r.targets?.map(x=>x.target),['acme.MatrixService'],r.message);put('src/main/java/x/Grid.java','package x; public class Grid {}');put('src/main/java/y/Grid.java','package y; public class Grid {}');put('src/test/java/z/GridSmokeTest.java','package z; class GridSmokeTest {}');const tie=m.resolveTargets(c,'src/test/java/z/GridSmokeTest.java');assert.equal(tie.ambiguous,true);assert.deepEqual(tie.candidates.sort(),['x.Grid','y.Grid']);put('src/main/java/other/MatrixServiceImpl.java','package other; public class MatrixServiceImpl {}');put('src/test/java/acme/MatrixServiceImplSmokeTest.java','package acme; class MatrixServiceImplSmokeTest {}');assert.deepEqual(m.resolveTargets(c,'src/test/java/acme/MatrixServiceImplSmokeTest.java').targets?.map(x=>x.target),['acme.MatrixService'],'same package beats a longer class elsewhere');});
