test('CLI waive distinguishes stale results and protects agent application while allowing human application',async t=>{const f=fixture(t),sid='waiver-session';f.c.sid=sid;f.c.session=m.hash(sid);f.c.stateFile=path.join(f.c.data,'state',f.c.session+'.json');await m.register(f.c,f.test);const r=await m.runTarget(f.c,m.hash('acme.Foo'),async()=>({raw:raw()})),id=r.survivors[0].id,env={...process.env,CLAUDE_PLUGIN_DATA:f.c.root,MUTAGATE_SESSION:sid};for(const name of ['MUTAGATE_HOOK_SESSION','CODEX_THREAD_ID','CLAUDE_CODE_SESSION_ID','COPILOT_AGENT_SESSION_ID','COPILOT_CLI'])delete env[name];const cli=(extra={},apply=true)=>spawnSync(process.execPath,[path.resolve(import.meta.dirname,'../scripts/mutagate.mjs'),'waive',id,'--reason','equivalent',...(apply?['--apply']:[]),'--repo',f.c.repo],{env:{...env,...extra},encoding:'utf8'}),waivers=path.join(f.c.repo,'.mutagate/waivers.json');for(const name of ['MUTAGATE_HOOK_SESSION','CODEX_THREAD_ID','CLAUDE_CODE_SESSION_ID','COPILOT_AGENT_SESSION_ID','COPILOT_CLI']){const blocked=cli({[name]:sid});assert.equal(blocked.status,2,blocked.stderr);assert.match(blocked.stderr,/--apply is for humans/);assert.equal(fs.existsSync(waivers),false);assert.equal(cli({[name]:sid},false).status,0);}assert.equal(cli().status,0);assert.equal(JSON.parse(fs.readFileSync(waivers)).waivers[0].id,id);fs.rmSync(waivers);f.put(f.source,'package acme; class Foo { int x; }');const stale=cli({},false);assert.equal(stale.status,2);assert.match(stale.stderr,/re-scored.*check --wait 120/);f.put('.mutagate/config.json','{"allowAgentWaivers":true}');f.c.config.allowAgentWaivers=true;await m.runTarget(f.c,m.hash('acme.Foo'),async()=>({raw:raw()}));const allowed=cli({MUTAGATE_HOOK_SESSION:sid});assert.equal(allowed.status,0,allowed.stderr);assert.equal(fs.existsSync(waivers),true);});
